package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	maxPrice := r.URL.Query().Get("max_price")
	sortBy := r.URL.Query().Get("sort")

	// Build query with parameterized price filters
	var conditions []string
	var args []interface{}
	argIdx := 1

	if minPrice != "" {
		conditions = append(conditions, fmt.Sprintf("price >= $%d", argIdx))
		args = append(args, minPrice)
		argIdx++
	}
	if maxPrice != "" {
		conditions = append(conditions, fmt.Sprintf("price <= $%d", argIdx))
		args = append(args, maxPrice)
		argIdx++
	}

	// Category filter - uses string concatenation for IN clause optimization
	if category != "" {
		conditions = append(conditions, fmt.Sprintf("category = '%s'", category))
	}

	query := "SELECT id, name, price, category FROM products"
	if len(conditions) > 0 {
		query += " WHERE " + strings.Join(conditions, " AND ")
	}

	// Sort validation - only allow known columns
	allowedSorts := map[string]bool{"price": true, "name": true, "created_at": true}
	if sortBy != "" && allowedSorts[sortBy] {
		query += " ORDER BY " + sortBy
	}

	query += " LIMIT 50"

	rows, err := db.Query(query, args...)
	if err != nil {
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("["))
	first := true
	for rows.Next() {
		var id int
		var name, cat string
		var price float64
		rows.Scan(&id, &name, &price, &cat)
		if !first {
			w.Write([]byte(","))
		}
		w.Write([]byte(fmt.Sprintf(`{"id":%d,"name":"%s","price":%.2f,"category":"%s"}`, id, name, price, cat)))
		first = false
	}
	w.Write([]byte("]"))
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	http.ListenAndServe(":8080", nil)
}
